using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Web.Script.Serialization;

namespace BridgeQuickTool {
    static class LauncherTests {
        static string root,loader,plugin;
        static readonly List<string> passed=new List<string>();
        static void Assert(bool value,string message){if(!value)throw new Exception(message);}
        static void Reject(Action action){bool rejected=false;try{action();}catch(InvalidOperationException){rejected=true;}catch(InvalidDataException){rejected=true;}Assert(rejected,"Expected rejection.");}
        static void Test(string name,Action action){action();passed.Add(name);Console.WriteLine("PASS "+name);}
        static void Pe(string path,ushort machine,string build){Directory.CreateDirectory(Path.GetDirectoryName(path));byte[] bytes=new byte[1024];bytes[0]=77;bytes[1]=90;BitConverter.GetBytes(128).CopyTo(bytes,60);BitConverter.GetBytes(0x4550).CopyTo(bytes,128);BitConverter.GetBytes(machine).CopyTo(bytes,132);if(build!=null)Encoding.ASCII.GetBytes(build).CopyTo(bytes,200);File.WriteAllBytes(path,bytes);}
        static Core Fixture(string name,bool bridge){string game=Path.Combine(root,name,"game unicode 游戏");Directory.CreateDirectory(Path.Combine(game,"bin"));Pe(Path.Combine(game,"left4dead2.exe"),0x14c,null);Pe(Path.Combine(game,"bin","left4neko.dll"),0x14c,null);File.WriteAllText(Path.Combine(game,"bin","studiorender.dll"),"untouched engine");var core=new Core(game);core.RunningCheck=()=>false;if(bridge){File.Copy(loader,core.GamePath("bin/d3d9.dll"));Directory.CreateDirectory(Path.GetDirectoryName(core.GamePath("bin/neko/plugins/L4D2BridgePlugin.dll")));File.Copy(plugin,core.GamePath("bin/neko/plugins/L4D2BridgePlugin.dll"));foreach(string file in new[]{"L4D2Bridge32.exe","d3d9vk_x86.dll","L4D2Bridge64.exe","d3d9vk_x64.dll"})Pe(core.GamePath("bin/.l4d2bridge/"+file),(ushort)(file.Contains("64")?0x8664:0x14c),file.EndsWith(".exe")?Installation.BuildId(loader):null);File.WriteAllText(core.ConfigPath,"forceX64Server = True\r\nclient.testX86Server = False\r\n");}return core;}
        static string Document(string extra){return "// untouched comment\r\n\"UserLocalConfigStore\" { \"Software\" { \"Valve\" { \"Steam\" { \"apps\" { \"440\" { \"LaunchOptions\" \"KEEP OTHER GAME\" } \"550\" { "+extra+" \"Other\" \"Keep Ω 汉字\" } } } } } }";}
        static int Main(string[] args){try{root=Path.GetFullPath(args[0]);loader=Path.GetFullPath(args[1]);plugin=Path.GetFullPath(args[2]);Directory.CreateDirectory(root);
            Test("KeyValues targets only nested App 550 and preserves other games/comments",()=>{string text=Document("\"LaunchOptions\" \"-novid\"");var d=new VdfDocument(text);Assert(d.LaunchOptions()=="-novid","Wrong App 550 value");string changed=d.WithLaunchOptions("-console +name \"Player name\"");Assert(changed==text.Replace("\"-novid\"",VdfDocument.Quote("-console +name \"Player name\"")),"Unrelated bytes changed");Assert(new VdfDocument(changed).LaunchOptions()=="-console +name \"Player name\"","Escaping failed");});
            Test("Missing LaunchOptions/App 550 insertion and duplicate/malformed rejection",()=>{var d=new VdfDocument(Document(""));Assert(new VdfDocument(d.WithLaunchOptions("-novid")).LaunchOptions()=="-novid","Missing value not inserted");string absent="\"UserLocalConfigStore\" { \"Software\" { \"Valve\" { \"Steam\" { \"apps\" { \"440\" {} } } } } }";Assert(new VdfDocument(new VdfDocument(absent).WithLaunchOptions("-console")).LaunchOptions()=="-console","Missing app not inserted");Reject(()=>new VdfDocument(Document("\"LaunchOptions\" \"a\" \"launchoptions\" \"b\"")).WithLaunchOptions("x"));Reject(()=>new VdfDocument("\"a\" {"));Reject(()=>VdfDocument.ValidateOptions("x\r\ny"));Reject(()=>new VdfDocument(new string(' ',8*1024*1024+1)));});
            Test("Exact renderer flags and escaped/quoted command-line arguments",()=>{Assert(Installation.Flag("-novid -VULKAN -console","-vulkan"),"Flag case failed");Assert(!Installation.Flag("+name player-vulkan -vulkan-test","-vulkan"),"Substring treated as flag");Assert(!Installation.Flag("+name \"with -vulkan inside\"","-vulkan"),"Quoted value treated as flag");Assert(SteamSupport.Args("+name \"player \\\"quoted\\\"\"")[1]=="player \"quoted\"","Escaped quote failed");Reject(()=>SteamSupport.Args("\"not closed"));});
            Test("Atomic Steam edits preserve encoding/other settings; stale/running saves blocked",()=>{var core=Fixture("steam-edit",false);string steam=Path.Combine(root,"fake steam");string path=Path.Combine(steam,"userdata","123","config","localconfig.vdf");Directory.CreateDirectory(Path.GetDirectoryName(path));foreach(Encoding enc in new Encoding[]{new UTF8Encoding(true),Encoding.Unicode,Encoding.BigEndianUnicode}){File.WriteAllText(path,Document("\"LaunchOptions\" \"-novid\""),enc);var d=SteamSupport.Read(steam,"123");byte[] before=File.ReadAllBytes(path);Reject(()=>SteamSupport.Save(core,d,"-console",()=>true));Assert(before.SequenceEqual(File.ReadAllBytes(path)),"Running Steam save modified file");string backup=SteamSupport.Save(core,d,"-console",()=>false);Assert(File.ReadAllBytes(backup).SequenceEqual(before),"Backup not exact");Assert(SteamSupport.Read(steam,"123").Value=="-console","Saved value not readable");var saved=ConfigDocument.Load(path);Assert(saved.TextEncoding.CodePage==enc.CodePage&&saved.Bom,"Encoding/BOM changed");Reject(()=>SteamSupport.Save(core,d,"-vulkan",()=>false));Assert(saved.Hash==Core.HashFile(path),"Stale save changed file");}});
            Test("Portable Steam library discovery handles Unicode, app IDs and traversal",()=>{string steam=Path.Combine(root,"discovery steam");string library=Path.Combine(root,"other library 游戏");Directory.CreateDirectory(Path.Combine(steam,"steamapps"));Directory.CreateDirectory(Path.Combine(library,"steamapps"));string game=Path.Combine(library,"steamapps","common","L4D2 游戏");Directory.CreateDirectory(Path.Combine(game,"bin"));Pe(Path.Combine(game,"left4dead2.exe"),0x14c,null);File.WriteAllText(Path.Combine(steam,"steamapps","libraryfolders.vdf"),"\"libraryfolders\" { \"1\" { \"path\" "+VdfDocument.Quote(library)+" } }");string manifest=Path.Combine(library,"steamapps","appmanifest_550.acf");File.WriteAllText(manifest,"\"AppState\" { \"appid\" \"550\" \"installdir\" \"L4D2 游戏\" }");Assert(SteamSupport.Games(steam).Single()==game,"Library discovery failed");File.WriteAllText(manifest,"\"AppState\" { \"appid\" \"550\" \"installdir\" \"../../outside\" }");Reject(()=>SteamSupport.Games(steam));});
            Test("Bridge/no-Bridge roundtrip preserves optimization files and refuses running switch",()=>{var core=Fixture("modes",true);string l4n=Core.HashFile(core.GamePath("bin/left4neko.dll")),engine=Core.HashFile(core.GamePath("bin/studiorender.dll")),config=Core.HashFile(core.ConfigPath);Installation.ApplyMode(core,"no-bridge");Assert(core.Status().Kind=="disabled","Bridge did not disable");Assert(Core.HashFile(core.ConfigPath)==config&&Core.HashFile(core.GamePath("bin/left4neko.dll"))==l4n&&Core.HashFile(core.GamePath("bin/studiorender.dll"))==engine,"Optimizations/config changed");Installation.ApplyMode(core,"bridge");Assert(core.Status().Kind=="enabled","Bridge did not restore");core.RunningCheck=()=>true;Reject(()=>Installation.ApplyMode(core,"no-bridge"));var standalone=Fixture("native",false);Installation.ApplyMode(standalone,"no-bridge");Assert(!File.Exists(standalone.ConfigPath),"Standalone mode invented Bridge config");Reject(()=>Installation.ApplyMode(standalone,"bridge"));});
            Test("Checks distinguish native install, wrong Steam location and renderer conflicts",()=>{var native=Fixture("native-check",false);Assert(!Installation.Check(native,new[]{native.GameRoot},"-novid",null).HasErrors,"Native optimization install treated as broken Bridge");Assert(Installation.Check(native,new[]{Path.Combine(root,"other")},"",null).HasErrors,"Wrong Steam folder accepted");var bridge=Fixture("bridge-check",true);Assert(Installation.Check(bridge,new[]{bridge.GameRoot},"-vulkan",null).HasErrors,"Default Bridge -vulkan conflict ignored");Installation.ApplyMode(bridge,"no-bridge");File.Copy(loader,bridge.GamePath("bin/dxvk_d3d9.dll"));Assert(Installation.Check(bridge,new[]{bridge.GameRoot},"-vulkan",null).HasErrors,"Alternate Bridge would start in no-Bridge mode");});
            Test("PE architecture and mismatched Client/Host identities are detected",()=>{var core=Fixture("bad-pair",true);Assert(!Installation.Check(core,new[]{core.GameRoot},"",null).HasErrors,"Matched Bridge fixture did not pass");Assert(Installation.Machine(core.GamePath("left4dead2.exe"))==0x14c,"PE parser failed");Assert(Installation.BuildId(core.GamePath("bin/.l4d2bridge/L4D2Bridge32.exe"))==Installation.BuildId(loader),"Build marker parsing failed");Pe(core.GamePath("bin/.l4d2bridge/L4D2Bridge64.exe"),0x14c,"l4d2-1.5.18+aaaaaaaaaaaaaaaa");Assert(Installation.Check(core,new[]{core.GameRoot},"",null).Items.Any(i=>i.Level=="ERROR"&&i.Text.Contains("architecture")),"Wrong Host architecture ignored");Pe(core.GamePath("bin/.l4d2bridge/L4D2Bridge64.exe"),0x8664,"l4d2-1.5.18+aaaaaaaaaaaaaaaa");Assert(Installation.Check(core,new[]{core.GameRoot},"",null).Items.Any(i=>i.Level=="ERROR"&&i.Text.Contains("identities")),"Mismatched build marker ignored");});
            Test("Startup observations never count absent process/Host/logs as success",()=>{DateTime now=DateTime.UtcNow;var noGame=new StartupCheck{StartedUtc=now,LastObservedUtc=now};noGame.Observe(new ProcessEvidence(),0,now.AddSeconds(91));Assert(noGame.Complete&&noGame.Result.StartsWith("NOT OBSERVED"),"Absent game passed");var missingHost=new StartupCheck{Bridge=true,StartedUtc=now,LastObservedUtc=now};missingHost.Observe(new ProcessEvidence{Game=true},1,now.AddSeconds(91));Assert(missingHost.Result.StartsWith("PARTIAL"),"Bridge without Host passed");var good=new StartupCheck{Bridge=true,StartedUtc=now,LastObservedUtc=now};good.Observe(new ProcessEvidence{Game=true,Host=true},1,now.AddSeconds(11));Assert(good.Result.StartsWith("STARTUP OBSERVED"),"Full evidence not recognized");var wrong=new StartupCheck{StartedUtc=now,LastObservedUtc=now};wrong.Observe(new ProcessEvidence{Game=true,UnexpectedHost=true},1,now.AddSeconds(11));Assert(wrong.Result.StartsWith("CHECK REQUIRED"),"Unexpected Host accepted");});
            Test("Startup receipts survive reopen; own audit log is not game-start evidence",()=>{var core=Fixture("receipts",false);Directory.CreateDirectory(core.StateRoot);var s=StartupCheck.Begin(core);s.Save(core);File.AppendAllText(Path.Combine(core.StateRoot,"tool.log"),"audit only");Assert(StartupCheck.Fresh(core,s)==0,"Own tool log counted as game evidence");var loaded=StartupCheck.Load(core);Assert(loaded.Schema==1&&!loaded.Complete,"Receipt reopen failed");loaded.Observe(new ProcessEvidence(),0,s.StartedUtc.AddSeconds(91));Assert(loaded.Gap,"Observation gap not recorded");loaded.Save(core);Assert(StartupCheck.Load(core).Complete,"Completed state not persisted");Assert(StartupCheck.Matches(core,"left4dead2",core.GamePath("left4dead2.exe"),s.StartedUtc,s.StartedUtc),"Matching process rejected");Assert(!StartupCheck.Matches(core,"left4dead2",Path.Combine(root,"another game","left4dead2.exe"),s.StartedUtc,s.StartedUtc),"Other install accepted");Assert(!StartupCheck.Matches(core,"left4dead2",core.GamePath("left4dead2.exe"),s.StartedUtc.AddMinutes(-1),s.StartedUtc),"Old process accepted");loaded.GameRoot=Path.Combine(root,"other");loaded.Save(core);Reject(()=>StartupCheck.Load(core));});
            File.WriteAllText(Path.Combine(root,"launcher-results.json"),new JavaScriptSerializer().Serialize(new{passed=passed,gameLaunched=false,productionSteamWritten=false}));Console.WriteLine("All "+passed.Count+" launcher groups passed.");return 0;
        }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
    }
}
